import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/86-直击“犯罪现场”.md","filePath":"books/attached/86-直击“犯罪现场”.md","lastUpdated":1794316978000}'),n={name:"books/attached/86-直击“犯罪现场”.md"};function d(l,a,_,c,p,i){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"直击-犯罪现场",tabindex:"-1"},[s("直击“犯罪现场” "),e("a",{class:"header-anchor",href:"#直击-犯罪现场","aria-label":'Permalink to "直击“犯罪现场”"'},"​")],-1),e("p",null,"要是你与伴侣分手后又重修旧好，又会发生什么呢？阿米尔在哥伦比亚大学的同事麦隆·霍费尔（Myron Hofer），也是在亲子依恋心理学领域非常杰出的研究者，他在一项研究中有了非常奇妙的发现。当幼年小鼠跟母亲分离之后，就会出现一系列的生理反应：它们会变得不那么活跃；心跳会减慢；连生长激素的分泌都会减缓。在霍费尔的实验中，它逐渐将来自小鼠母亲的变量，替换为一些人为的手段：他先用发热的垫子来温暖小鼠，又将它们喂得饱饱的，接着用小刷子轻轻抚摸它们，就仿佛妈妈的舌头在舔一样。霍费尔发现，每一种手段都能在某一方面减轻他们分离后的焦虑。食物投喂能让小鼠宝宝们的心率恢复正常，温暖的垫子能让它们保持活动水平，而轻轻抚拍则促进了生长激素的分泌。",-1),e("p",null,"而一旦让它们跟母亲重逢，简单一个动作就能让所有不正常的症状瞬间消失。对于人类来说，情况也是非常类似的。我们和他人断绝关系的时候，依恋机制是在超负荷工作的。我们就像那些老鼠宝宝一样，一心只想回到曾经深爱的人身边。事实证明，人们会在分手的那一秒忘掉之前所有的不愉快，一心只想着再次见到对方。即使是两人同处一个房间，也能在一定程度上减轻焦虑，而达到身边亲戚朋友怎么安慰都达不到的效果。",-1),e("p",null,"正因为如此，很多人会发现下定决心分手是件很难的事情，往往是屡次做出决定却依旧失败。这也就是为什么玛莎在分手很久以后，依然和克雷格保持着联系了。焦虑型依恋风格的人，往往会花很长的时间来忍受糟糕依恋关系的煎熬，而他们根本没办法了结这段无止境的煎熬。只有当全身每个细胞都开始承认伴侣根本无可救药，他们根本不可能重修旧好，这时候焦虑型人群才会舍得放手。",-1)])])}const h=t(n,[["render",d]]);export{m as __pageData,h as default};
